Pendiente reciente
Puede estimarse la tendencia de una ventana.
import numpy as np

def calculate_slope(
    values
):

    if len(values) &lt; 2:
        return np.nan

    x = np.arange(
        len(values)
    )

    return np.polyfit(
        x,
        values,
        1
    )[0]
df[
    "heart_rate_slope_4"
] = (
    df
    .groupby("patient_id")[
        "heart_rate"
    ]
    .transform(
        lambda series:
        series
        .shift(1)
        .rolling(
            window=4
        )
        .apply(
            calculate_slope,
            raw=True
        )
    )
)

