Pendiente con tiempo real
En series irregulares, la pendiente debe considerar tiempos reales.
def time_aware_slope(
    values,
    timestamps
):

    if len(values) &lt; 2:
        return np.nan

    hours = (
        timestamps
        -
        timestamps[0]
    ).total_seconds() / 3600

    return np.polyfit(
        hours,
        values,
        1
    )[0]

